"""Eight SHAKE/RATTLE records from visually checked PDF183–184."""
from ch04_data import add,copied,proposition,D
add('SHAKEPositionPrinted','4.3.5',161,[64],r'''In the presence of the constraint, we consider the scheme
\[q_{n+1}-2q_n+q_{n-1}=h^2M^{-1}F(q_n)-h^2g'(q_n)^T\lambda_n,\tag{4.25}\]
\[g(q_{n+1})=0.\tag{4.26}\]''',copied(D,'shakePositionPrinted'),kind='definition',verdict='NEEDS_HUMAN',explanation='保留印刷约束反力缺M⁻¹；与相空间消元一般质量版本不一致。',issues=[dict(code='ERRATUM?',detail='(4.25)约束反力未带M⁻¹；一般非标量对角质量不能任意吸收入λ。')])
add('SHAKEPositionMass','4.3.5',161,[],r'''It is possible to demonstrate (see exercises) that this method reduces to (4.25)–(4.26) by eliminating the momenta.''',copied(D,'shakePositionRelation'),kind='definition',extra=['[EXTRA]质量一致位置式h²M⁻¹(F−Gᵀλ)，非原印刷(4.25)。'])
add('SHAKEPhase','4.3.5',161,[65],r'''A natural choice is to consider the phase space formulation of the Störmer-Verlet method for $\dot q=M^{-1}p,\dot p=F(q)$, then replace $F$ by $F-g'(q)^T\lambda$, resulting in
\[q_{n+1}=q_n+hM^{-1}p_{n+1/2},\tag{4.27}\]
\[p_{n+1/2}=p_n+(h/2)F(q_n)-(h/2)g'(q_n)^T\lambda_n,\tag{4.28}\]
\[p_{n+1}=p_{n+1/2}+(h/2)F(q_{n+1})-(h/2)g'(q_{n+1})^T\lambda_{n+1}.\tag{4.29}\]''',copied(D,'shakeRelation'),kind='definition',context=['含真实位置约束分支；不声称隐藏约束成立或隐式分支存在。'])
add('RATTLE','4.3.5',161,[66],r'''A method that automatically preserves both the constraint and hidden constraint is the RATTLE method [12] which consists of the following steps:
\[q_{n+1}=q_n+hM^{-1}p_{n+1/2},\tag{4.30}\]
\[p_{n+1/2}=p_n+(h/2)F_n-(h/2)g'(q_n)^T\lambda_n,\tag{4.31}\]
\[0=g(q_{n+1}),\tag{4.32}\]
\[p_{n+1}=p_{n+1/2}+(h/2)F_{n+1}-g'(q_{n+1})^T\mu_{n+1},\tag{4.33}\]
\[0=g'(q_{n+1})M^{-1}p_{n+1}.\tag{4.34}\]''',copied(D,'rattleRelation'),kind='definition',context=['完整关系，包括两个不同乘子缩放；定义不计解存在证明。'])
add('ConstrainedOrders','4.3.5','161–162',[67],r'''The projected symplectic constrained method (4.20)–(4.24) is only first order accurate. We forego providing a detailed proof of this fact, but note that it could be demonstrated using standard methods [164]. There are several constraint-preserving, second-order alternatives which generalize the Störmer-Verlet scheme. One of these is the SHAKE method [322]. The symmetry suggests that this will be second order.''',proposition('constrainedOrders_statement'),extra=['正质量、C⁴数据、独立约束与真实光滑隐式解分支及紧区间；明确局部截断误差Euler O(h²)、RATTLE O(h³)。'],missing='缺实际约束ODE与隐式分支的高阶Taylor/一致误差理论；不建设大型收敛理论。')
add('RATTLESymplectic','4.3.5',162,[68],r'''Moreover, the symplecticness of (4.30)–(4.34) may be demonstrated using a very similar approach to that used to demonstrate the symplectic condition for (4.20)–(4.24). Given the above discussion and derivation, the proof of symplecticness of the RATTLE method (4.30)–(4.34) is now a formality. For details refer to [229].''',proposition('rattleSymplectic_statement'),extra=['实际C¹分支、C²势与约束；完整真实拉回两形式，非把辛性作假设。'],missing='待桥接已证多约束动量kick、位置drift与末逆Gram投影；若无简短接口保持sorry。')
add('StaggeredConstraint','4.3.5',162,[69],r'''the iterations generated by them can be related to the following staggered iteration
\[q_{n+1}=q_n+hM^{-1}p_{n+1/2},\tag{4.35}\]
\[p_{n+1/2}=p_{n-1/2}+hF_n-hg'(q_n)^T\widetilde\lambda_n,\tag{4.36}\]
\[0=g(q_{n+1}),\tag{4.37}\]
where, for SHAKE, $\widetilde\lambda_n=\lambda_n$, while, in case of RATTLE, we must define $\widetilde\lambda_n=(\lambda_n+\mu_n)/2$.''',copied(D,'staggeredConstraintRelation'),kind='definition',context=['原μ在(4.33)无h/2，而此处平均式有缩放疑点，固定n下相容半步对象另条。'],issues=[dict(code='ERRATUM?',detail='p162的平均乘子需与p161(4.33)无h/2缩放一致；未将未经核定平均关系计为证明。')])
add('SHAKERATTLEEquivalence','4.3.5',162,[70],r'''Given an initial condition $(q_0^S,p_0^S)$ for the SHAKE discretization, we easily determine $\lambda_0^S$ by taking a step. Then it follows that
\[p_{-1/2}=p_0-(h/2)F(q_0^S)-(h/2)g'(q_0^S)^T\lambda_0^S,\]
by solving (4.29). Next we obtain $p_0^R$ by solving (4.33)–(4.34) with $n=-1$. Then the sequences generated using $(q_0^S,p_0^S)$ as the initial point for SHAKE and that generated using $(q_0^S,p_0^R)$ in RATTLE will have identical positions (the momenta can be made compatible by simply projecting the SHAKE momenta onto the constraints).''',proposition('shakeRattlePositions_statement').replace('h ≠ 0 → (∀ i, 0 < m i) →','h ≠ 0 → (∀ i, 0 < m i) →\n    (∀ q, q ∈ MolecularDynamics.Chapter04Review.constraintSet g →\n      LinearIndependent ℝ (fun j => textbookConstraintGradient (g j) q)) →'),extra=['真实两套关系、相容初始半动量、正质量和同一局部唯一投影分支；不假设位置序列相同。','[EXTRA]位置约束上梯度线性独立，保证显式逆Gram投影有定义；旧命题此资格缺失，不静默忽略。'],issues=[dict(code='ERRATUM?',detail='展示初始p−1/2从(4.29)消元的反力符号需核；原句保持。')],missing='缺真实约束求解分支唯一性与跨步乘子缩放桥接；不建立隐式求解理论。')
